// Example: single call with per-read deadline
ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
defer cancel()
client := sdk.NewStreamClient(sdk.WithPerReadTimeout(500*time.Millisecond))
stream, err := client.Start(ctx, req)
if err != nil { return err }
for {
    chunk, err := stream.Recv(ctx) // Recv honors per-read timeout; returns ErrStreamTimeout on per-read timeout
    if err != nil {
        return err // caller can choose to Retry if ErrStreamResumable
    }
    process(chunk)
}

// Example: resumable large response
client := sdk.NewStreamClient(sdk.WithResumeEnabled(true))
stream, err := client.Start(ctx, largeReq)
for {
    chunk, err := stream.Recv(ctx)
    if err == sdk.ErrStreamResumable {
        // stream may include a resume token; Resume will attempt reconnect with backoff
        if resumeErr := stream.Resume(ctx); resumeErr != nil {
            return resumeErr
        }
        continue
    } else if err != nil {
        return err
    }
    buffer.Write(chunk.Data)
}
